llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C15"],
      "claim": "Delpazolid (LCB01-0371), an oxazolidinone sharing the fluorophenyl-oxazolidinone core, had 99.75% absolute oral bioavailability in healthy volunteers, strongly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Linezolid, a close oxazolidinone analogue, has ~100% oral bioavailability in humans, supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Fosravuconazole L-lysine ethanolate, a phosphate ester prodrug, achieves 100% oral bioavailability in humans, supporting high F for the query's phosphate prodrug motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Fludarabine monophosphate, a phosphate-containing drug, has 70% oral bioavailability in humans, above the 20% threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "YH4808, an oxazolidinone with a thiomorpholine substituent, had low absolute oral bioavailability (10.1%), a contradictory example; however, it lacks the tetrazole-pyridine and phosphate features of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Cadazolid, an oxazolidinone-containing antibiotic, had very low oral bioavailability in healthy subjects, a contradictory example; its large polar quinolone-piperidine substituents differ markedly from the query's tetrazole-pyridine phosphate.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Cytarabine ocfosfate, a phosphate-containing prodrug, had only 15.8% metabolic bioavailability in patients, a contradictory example for phosphate prodrugs; its nucleoside/lipid structure is distant from the oxazolidinone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a phosphate prodrug of a tedizolid-like oxazolidinone. High oral bioavailability is strongly supported by delpazolid (99.75%), linezolid (~100%), and the phosphate prodrug fosravuconazole (100%), with fludarabine phosphate (70%) also above threshold. Low-F oxazolidinone and phosphate examples are structurally distinct and do not override the strong high-F evidence.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is included in the provided evidence.",
    "The query's phosphate group introduces prodrug-conversion and solubility considerations not fully captured by the non-phosphate oxazolidinone analogues.",
    "Low-F phosphate/nucleoside analogues indicate that phosphate prodrugs are not universally high-F, but their structural dissimilarity limits transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

